actions.script:
let out = {}, errors = null
try {
    // the JSON parameters; a SQL source only from the body, never the URL
    const parse = (name, fallback) => {
        const text = ec.web.secureRequestParameters[name] != null ? ec.web.secureRequestParameters[name] : context[name]
        if (text == null || text === '') return fallback
        try { return JSON.parse(String(text)) } catch (e) { throw new Error(name + ' is not JSON') }
    }
    const source = parse('sourceJson', null)
    if (source && source.type == 'sql' && ec.web.secureRequestParameters.sourceJson == null) throw new Error('A SQL source goes in the request body')
    out = ec.service.sync().name('org.moqui.impl.DatabaseServices.get#DataGridColumns').parameters({source, columns: parse('columnsJson', [])}).call() || {}
} catch (e) { errors = String(e.message || e) }
if (ec.message.hasError()) errors = ec.message.errorsString
ec.message.clearErrors()
ec.web.sendJsonResponse(Object.assign({}, out, {errors}))

