    out = ec.service.sync().name('org.moqui.impl.DatabaseServices.export#DataGrid').parameters({source, columns: parse('columnsJson', []), sort: parse('sortJson', []), filter: parse('filterJson', []), format: context.format || 'csv',
        location: context.location || null}).call() || {}
} catch (e) { errors = String(e.message || e) }
if (ec.message.hasError()) errors = ec.message.errorsString
ec.message.clearErrors()
ec.web.sendJsonResponse(Object.assign({}, out, {errors}))

const location = String(context.location || '')
const prefix = 'runtime://tmp/grid-export/' + ec.user.userId + '/'
const rest = location.startsWith(prefix) ? location.substring(prefix.length) : null
if (!ec.user.userId || rest == null || !rest || rest.split('/').some((segment) => segment == '..' || segment == '.' || segment == '')
        || !ec.resource.getLocationReference(location)?.getExists()) {
    ec.web.sendJsonError(404, ec.l10n.localize('Export not found'))
} else {
    const fileName = String(context.fileName || rest.split('/').pop()).replace(/[\\/"\r\n]/g, '_')
    ec.web.sendResourceResponse(location, false, fileName)
    // the export's own type (text/csv, the XLSX type), not one guessed from the name
    const types = ['text/csv', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet']
    if (types.includes(String(context.contentType || ''))) ec.web.response.setContentType(String(context.contentType))
}

