        sourceJson: String(ec.web.secureRequestParameters.viewSourceJson || ''), layoutJson: ec.web.secureRequestParameters.layoutJson || null}).call() || {}
} catch (e) { errors = String(e.message || e) }
if (ec.message.hasError()) errors = ec.message.errorsString
