    out = ec.service.sync().name('org.moqui.impl.DatabaseServices.delete#GridView').parameters({viewId: String(context.viewId || '')}).call() || {}
} catch (e) { errors = String(e.message || e) }
if (ec.message.hasError()) errors = ec.message.errorsString
ec.message.clearErrors()
