const term = String(context.term || '').toLowerCase()
const names = term ? ec.entity.getAllEntityNames().filter((name) => String(name).toLowerCase().includes(term)).slice(0, 50) : []
let related = null
const name = String(context.entityName || '')
try {
    let relatedName = null
    if (name.startsWith('DataDocument.')) {
        const doc = ec.entity.find('moqui.entity.document.DataDocument').condition('dataDocumentId', name.substring(13)).one()
        relatedName = doc ? doc.primaryEntityName : null
    } else if (name) {
        const master = ec.entity.find('moqui.entity.view.DbViewEntityMember').condition('dbViewEntityName', name).condition('entityAlias', 'MASTER').one()
        relatedName = master ? master.entityName : null
    }
    if (relatedName && ec.entity.isEntityDefined(relatedName))
        related = {entityName: relatedName, pkFieldNames: ec.entity.getEntityDefinition(relatedName).getPkFieldNames()}
} catch (e) { related = null }
ec.message.clearErrors()
ec.web.sendJsonResponse({entityNames: names, userId: ec.user.userId, canSql: ec.user.hasPermission('SQL_RUNNER_WEB'), related})

render-mode.text:
${JSON.stringify((() => {
                const name = String(selectedEntity || entityName || '')
                if (!name) return [{t: 'text', id: 'GridChoose', text: 'Name an entity: Data › Grid?entityName=...'}]
                const pageIndex = Math.max(0, parseInt(context.pageIndex || '0', 10) || 0)
                const size = 20
                const call = (service, parameters) => {
                    const out = ec.service.sync().name('org.moqui.impl.DatabaseServices.' + service).parameters(parameters).call() || {}
                    const error = ec.message.hasError() ? ec.message.errorsString : null
                    ec.message.clearErrors()
                    return {out, error}
                }
                const source = {type: 'entity', entityName: name}
                const columns = call('get#DataGridColumns', {source})
                if (columns.error) return [{t: 'text', id: 'GridError', style: 'error', text: columns.error}]
                const shown = (columns.out.columns || []).slice(0, 8)
                const rows = call('get#DataGridRows', {source, columns: shown.map((column) => column.name), page: pageIndex + 1, size})
                if (rows.error) return [{t: 'text', id: 'GridError', style: 'error', text: rows.error}]
                const data = rows.out.data || []
                const keys = (columns.out.columns || []).filter((column) => column.pk).map((column) => column.name)
                const editable = !!columns.out.entityName && !name.startsWith('DataDocument.')
                const recordUrl = (row) => {
                    let url = sri.buildUrl('../Record').addParameter('selectedEntity', name)
                    for (const key of keys) url = url.addParameter(key, row[key] == null ? '' : String(row[key]))
                    return url.getUrlWithParams()
                }
                const text = (value) => value == null ? '' : typeof value === 'object' ? JSON.stringify(value) : String(value)
                const count = Number(rows.out.last_row || (pageIndex * size + data.length))
                return [{t: 'text', id: 'GridTitle', style: 'h5', text: name},
                    {t: 'formList', id: 'GridRows', name: 'GridRows', columns: shown.map((column) => ({title: column.title || column.name})).concat(editable ? [{title: ''}] : []),
                        rows: data.map((row, index) => ({id: String(index), cells: shown.map((column) => text(row[column.name]))
                            .concat(editable ? [{t: 'link', id: 'GridEdit' + index, text: 'Edit', url: recordUrl(row), kind: 'anchor'}] : [])})),
                        paging: {index: pageIndex, size, count, maxIndex: Math.max(0, Math.ceil(count / size) - 1),
                            rangeLow: data.length ? pageIndex * size + 1 : 0, rangeHigh: pageIndex * size + data.length}}]
            })())}
